const body = $json.body || $json;

// Error Trigger in n8n delivers execution context under execution
const execution = $json.execution || {};
const workflow = $json.workflow || {};

const wfName = body.workflow_name || workflow.name || 'Unknown Workflow';
const execId = body.execution_id || String(execution.id || 'N/A');
const errCode = body.error_code || (execution.error && execution.error.name) || 'PIPELINE_ERROR';
const errMsg = body.error_message || (execution.error && execution.error.message) || 'Workflow execution terminated with error';
const failureCat = body.failure_category || null;
const corrId = body.correlation_id || ('corr_inc_' + Math.random().toString(36).substring(2, 10));

return [{
  json: {
    workflow_name: wfName,
    execution_id: execId,
    error_code: errCode,
    error_message: errMsg,
    failure_category: failureCat,
    correlation_id: corrId,
    error_details: {
      source_node: (execution.error && execution.error.node) || 'Unknown Node',
      timestamp: new Date().toISOString()
    }
  }
}];

const inc = $json.data || {};
const corrId = $json.correlation_id || 'unknown';

return [{
  json: {
    workflow: 'WF08 - Centralized Failure Recovery & Incident Management',
    status: 'RECORDED',
    incident_id: inc.incident_id,
    workflow_name: inc.workflow_name,
    execution_id: inc.execution_id,
    failure_category: inc.failure_category,
    severity: inc.severity,
    incident_status: inc.status,
    eligible_for_retry: inc.eligible_for_retry,
    suggested_backoff_seconds: inc.suggested_backoff_seconds,
    retry_count: inc.retry_count,
    max_retries: inc.max_retries,
    correlation_id: corrId,
    message: `Operational incident '${inc.incident_id}' registered for '${inc.workflow_name}'. Status: ${inc.status} (${inc.failure_category}/${inc.severity}).`
  }
}];
